var state: u64 = 12345;
var counts: [13]u32 = @splat(0);
for (0..1000) |_| {
    state = (state * 48271) % 2147483647;
    const a = state % 6 + 1;
    state = (state * 48271) % 2147483647;
    const b = state % 6 + 1;
    counts[@intCast(a + b)] += 1;
var best: usize = 2;
for (2..13) |sum| {
    try out.print("{d}: {d}\n", .{ sum, counts[sum] });
    if (counts[sum] > counts[best])
        best = sum;
try out.print("most frequent: {d}\n", .{best});
